    if value > high:
        return "above"
    return "inside"

def count_unknown(commands):
    count = 0
    for symbol in commands:
        if symbol not in "LR.":
            count = count + 1
    return count

def longest_signal(signal):
    current = 0
    best = 0
    for symbol in signal:
        if symbol == "1":
            current = current + 1
            if current > best:
                best = current
        else:
            current = 0
    return best

def first_return(commands):
    position = 0
    for index in range(len(commands)):
        if commands[index] == "L":
            position = position - 1
        else:
            position = position + 1
        if position == 0:
            return index + 1
    return None

def compress_runs(text):
    if text == "":
        return ""
    result = ""
    previous = text[0]
    count = 0
    for symbol in text:
        if symbol == previous:
            count = count + 1
        else:
            result = result + previous + str(count)
            previous = symbol
            count = 1
    # ponytail: строковая сборка ограничена 1000 символами входа; для больших
    # потоков после изучения списков перейти к накоплению частей и join.
    return result + previous + str(count)

