def import_annotations(text):
    import csv,io
    accepted=[];rejected=[]
    numeric=["width","height","x1","y1","x2","y2"]
    for row,raw in enumerate(csv.DictReader(io.StringIO(text)),2):
        r={k:v.strip() for k,v in raw.items()}
        reason=None
        if any(v=="" for v in r.values()): reason="empty"
        else:
            try:
                for k in numeric: r[k]=int(r[k])
            except ValueError: reason="number"
            if reason is None and not (0<=r["x1"]<r["x2"]<=r["width"] and 0<=r["y1"]<r["y2"]<=r["height"]): reason="bounds"
        if reason: rejected.append(dict(row=row,reason=reason))
        else: accepted.append(r)
    return dict(accepted=accepted,rejected=rejected)

def annotation_counts(accepted):
