def batches(values,size):
    batch=[]
    for value in values:
        batch.append(value)
        if len(batch)==size:
            yield batch
            batch=[]
    if batch:
        yield batch

def dense_window(times,width):
    left=0;best=0
    for right,value in enumerate(times):
        while value-times[left]>=width:
            left+=1
        best=max(best,right-left+1)
    return best

