    total=sum(n for mean,n in groups)
    return sum(mean*n for mean,n in groups)/total if total else None

def average_known(values):
    known=[x for x in values if x is not None]
    return sum(known)/len(known) if known else None

def count_report(rows):
    accepted=[];rejected=[]
    for i,text in enumerate(rows,1):
        try: value=int(text)
        except ValueError:
            rejected.append(i);continue
        if value<0: rejected.append(i)
        else: accepted.append(value)
    return {"accepted":accepted,"rejected":rejected,"total":sum(accepted)}

