def binary_metrics(y,pred):
    tp=sum(a==1 and b==1 for a,b in zip(y,pred))
    fp=sum(a==0 and b==1 for a,b in zip(y,pred))
    fn=sum(a==1 and b==0 for a,b in zip(y,pred))
    tn=sum(a==0 and b==0 for a,b in zip(y,pred))
    return dict(tp=tp,fp=fp,fn=fn,tn=tn,accuracy=(tp+tn)/len(y) if y else None,precision=tp/(tp+fp) if tp+fp else None,recall=tp/(tp+fn) if tp+fn else None)

def neuron(x,w,b,target):
    prediction=sum(a*weight for a,weight in zip(x,w))+b
    return prediction,(prediction-target)**2

def descent(w,target,rate,steps):
    history=[w]
    for _ in range(steps):
        w-=rate*2*(w-target)
        history.append(w)
    return history

def split_frames(frames,test_videos):
    train=[];test=[]
    for frame in frames:
        (test if frame["video_id"] in test_videos else train).append(frame)
    return train,test

def audit_split(train,valid,test):
    a,b,c=set(train),set(valid),set(test)
    return dict(train_valid=sorted(a&b),train_test=sorted(a&c),valid_test=sorted(b&c))

def collect_pages(pages,start):
    visited=set();ids=set();result=[]
    while start is not None and start not in visited:
        visited.add(start);page=pages[start]
        for item in page["items"]:
            if item["id"] not in ids:
                ids.add(item["id"]);result.append(item)
        start=page["next"]
    return result

def import_events(connection,rows):
    connection.execute("CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, value INTEGER)")
    with connection:
        connection.executemany("INSERT INTO events VALUES (?, ?) ON CONFLICT(id) DO NOTHING",rows)
    return connection.execute("SELECT id,value FROM events ORDER BY id").fetchall()
